package com.autojobapply.discovery;
import com.autojobapply.model.Job; import com.google.gson.*; import java.net.*; import java.net.http.*; import java.time.*; import java.util.*;
public final class GreenhouseJobDiscoveryService { private final HttpTextClient http; public GreenhouseJobDiscoveryService(){this(new JavaHttpTextClient());}public GreenhouseJobDiscoveryService(HttpTextClient http){this.http=http;}
 public List<Job> retrieve(GreenhouseCompanyDiscoveryService.Board board)throws Exception{List<Job>out=new ArrayList<>();for(JsonElement e:JsonParser.parseString(http.get(URI.create("https://boards-api.greenhouse.io/v1/boards/"+board.token()+"/jobs?content=true"))).getAsJsonObject().getAsJsonArray("jobs")){JsonObject o=e.getAsJsonObject();String location=o.has("location")?o.getAsJsonObject("location").get("name").getAsString():"";out.add(new Job("Greenhouse",board.company(),o.get("title").getAsString(),location,o.has("content")?o.get("content").getAsString().replaceAll("<[^>]*>"," "):"",o.get("id").getAsString(),o.get("absolute_url").getAsString(),o.get("absolute_url").getAsString()));}return out;}}
